    Circle { r: f64 },
    Rect { w: f64, h: f64 },
    Triangle { b: f64, h: f64 },
}
fn area(s: &Shape) -> f64 {
    match s {
        Shape::Circle { r } =>
            3.14 * r * r,
        Shape::Rect { w, h } => w * h,
    }
}
```

